def fact(identifier, text, value, **metadata):
    return {"id": identifier, "text": text, "value": value, **metadata}


def case(index, question, episodes, proof, *, note):
    return {"source_profile_index": index, "question": question, "episodes": episodes,
            "proof": proof, "semantic_review_note": note}


